### 3. CODIFICAÇÃO EM JAVA

```java
import java.io.*;
import java.util.*;

public class Main {

    static final long OFFSET = 300000L;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int Q = fs.nextInt();
        long K = fs.nextLong();

        long[] A = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            A[i] = fs.nextLong();
        }

        int[] D = new int[Q + 1];
        int[] death = new int[N + 1];
        for (int t = 1; t <= Q; t++) {
            D[t] = fs.nextInt();
            death[D[t]] = t;
        }

        int nextTime = Q + 1;
        for (int i = 1; i <= N; i++) {
            if (death[i] == 0) {
                death[i] = nextTime++;
            }
        }

        // Construção da Árvore Cartesiana (min-heap em death)
        int[] left = new int[N + 1];
        int[] right = new int[N + 1];
        int[] stack = new int[N + 1];
        int top = 0;

        for (int i = 1; i <= N; i++) {
            int last = 0;
            while (top > 0 && death[stack[top]] > death[i]) {
                last = stack[top--];
            }
            if (top > 0) {
                right[stack[top]] = i;
            }
            left[i] = last;
            stack[++top] = i;
        }
        int root = stack[1];

        // Determinação iterativa de L[u] e R[u] (evita StackOverflowError)
        int[] L = new int[N + 1];
        int[] R = new int[N + 1];
        int[] postOrder = new int[N];
        int pIdx = 0;
        int[] s2 = new int[N + 1];
        boolean[] visited = new boolean[N + 1];
        int top2 = 0;
        s2[++top2] = root;

        while (top2 > 0) {
            int u = s2[top2];
            if (visited[u]) {
                top2--;
                postOrder[pIdx++] = u;
            } else {
                visited[u] = true;
                if (right[u] != 0) s2[++top2] = right[u];
                if (left[u] != 0) s2[++top2] = left[u];
            }
        }

        for (int i = 0; i < N; i++) {
            int u = postOrder[i];
            L[u] = (left[u] != 0 ? L[left[u]] : u);
            R[u] = (right[u] != 0 ? R[right[u]] : u);
        }

        // Preparação das chaves compostas ordenadas para busca binária
        long[] sortedPlus = new long[N];
        long[] sortedMinus = new long[N];
        for (int i = 1; i <= N; i++) {
            long valPlus = A[i] + i;
            sortedPlus[i - 1] = (valPlus << 32) | (long) i;

            long valMinus = A[i] - i + OFFSET;
            sortedMinus[i - 1] = (valMinus << 32) | (long) i;
        }

        Arrays.sort(sortedPlus);
        Arrays.sort(sortedMinus);

        // Contagem de pares para cada nó u
        long[] pairsLostAt = new long[N + 1];

        for (int u = 1; u <= N; u++) {
            int lenL = u - L[u];
            int lenR = R[u] - u;
            long count = 0;

            if (lenL <= lenR) {
                // Itera pelo lado esquerdo
                for (int i = L[u]; i <= u; i++) {
                    long jStart = Math.max(u, i + 1);
                    long jEnd = Math.min((long) R[u], (long) i + K);

                    if (jStart <= jEnd) {
                        // Caso A: A_j - j = A_i - i - K
                        long targetMinus = A[i] - i - K;
                        long valMinus = targetMinus + OFFSET;
                        if (valMinus >= 0) {
                            long low = (valMinus << 32) | jStart;
                            long high = (valMinus << 32) | jEnd;
                            count += upperBound(sortedMinus, high) - lowerBound(sortedMinus, low);
                        }

                        // Caso B: A_j + j = A_i + i + K
                        long targetPlus = A[i] + i + K;
                        if (targetPlus >= 0) {
                            long low = (targetPlus << 32) | jStart;
                            long high = (targetPlus << 32) | jEnd;
                            count += upperBound(sortedPlus, high) - lowerBound(sortedPlus, low);
                        }

                        // Deduplicação se j - i == K e A[j] == A[i]
                        long jDouble = (long) i + K;
                        if (jDouble >= jStart && jDouble <= jEnd) {
                            if (A[(int) jDouble] == A[i]) {
                                count--;
                            }
                        }
                    }
                }
            } else {
                // Itera pelo lado direito
                for (int j = u; j <= R[u]; j++) {
                    long iStart = Math.max((long) L[u], (long) j - K);
                    long iEnd = Math.min((long) u, (long) j - 1);

                    if (iStart <= iEnd) {
                        // Caso A: A_i - i = A_j - j + K
                        long targetMinus = A[j] - j + K;
                        long valMinus = targetMinus + OFFSET;
                        if (valMinus >= 0) {
                            long low = (valMinus << 32) | iStart;
                            long high = (valMinus << 32) | iEnd;
                            count += upperBound(sortedMinus, high) - lowerBound(sortedMinus, low);
                        }

                        // Caso B: A_i + i = A_j + j - K
                        long targetPlus = A[j] + j - K;
                        if (targetPlus >= 0) {
                            long low = (targetPlus << 32) | iStart;
                            long high = (targetPlus << 32) | iEnd;
                            count += upperBound(sortedPlus, high) - lowerBound(sortedPlus, low);
                        }

                        // Deduplicação se j - i == K e A[j] == A[i]
                        long iDouble = (long) j - K;
                        if (iDouble >= iStart && iDouble <= iEnd) {
                            if (A[(int) iDouble] == A[j]) {
                                count--;
                            }
                        }
                    }
                }
            }

            pairsLostAt[death[u]] += count;
        }

        // Cálculo das respostas para cada minuto t = 0 ... Q
        long currentAns = 0;
        for (int t = 1; t <= N; t++) {
            currentAns += pairsLostAt[t];
        }

        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.println(currentAns);

        for (int t = 1; t <= Q; t++) {
            currentAns -= pairsLostAt[t];
            out.println(currentAns);
        }

        out.flush();
    }

    static int lowerBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] >= key) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static int upperBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] > key) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ' && c != -1) c = read();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }

        public long nextLong() throws IOException {
            int c = read();
            while (c <= ' ' && c != -1) c = read();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            long res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }
    }
}
